    38→type LoginWithUsernameAndPasswordData = {
    39→  username: string;
    40→  password: string;
    41→};
    42→
    43→/** Callback function for verification request received */
    44→type VerificationRequestCallback = (
    45→  details: SessionVerificationRequestDetails,
    46→) => void;
    47→
    48→/** Callback function for emojis received during verification */
    49→type VerificationEmojisCallback = (
    50→  emojis: Array<{ symbol: string; description: string }>,
    51→) => void;
    52→
    53→/** Callback function for verification state changes */
    54→type VerificationStateChangeCallback = (
    55→  state:
    56→    | "request"
    57→    | "accepted"
    58→    | "emojis"
    59→    | "success"
    60→    | "failed"
    61→    | "cancelled"
    62→    | "sasStarted",
    63→) => void;
    64→
    65→const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/data`;
    66→const cachePath = `${RNFS.CachesDirectoryPath}/matrix/cache`;
    67→
    68→const APP_ID = "com.prototyp.cloak";
    69→
    70→export class MatrixService {
    71→  //TODO: change every method that uses MatrixService.instance to a class method
    72→  public static instance: ClientInterface | null;
    73→  public static syncService: SyncServiceInterface | null;
    74→  private static verificationController: SessionVerificationControllerInterface | null =
    75→    null;
    76→  public static profile: UserProfile | null = null;
    77→
    78→  // Verification callbacks
    79→  private static onVerificationRequest: VerificationRequestCallback | null =
    80→    null;
    81→  private static onVerificationEmojis: VerificationEmojisCallback | null = null;
    82→  private static onVerificationStateChange: VerificationStateChangeCallback | null =
    83→    null;
    84→
    85→  /** Clear the crypto store directories to fix device ID mismatches */
    86→  private static async clearCryptoStore() {
    87→    try {
    88→      const dataExists = await RNFS.exists(dataPath);
    89→      const cacheExists = await RNFS.exists(cachePath);
    90→
    91→      if (dataExists) {
    92→        await RNFS.unlink(dataPath);
    93→        console.log("Cleared crypto data store");
    94→      }
    95→
    96→      if (cacheExists) {
    97→        await RNFS.unlink(cachePath);
    98→        console.log("Cleared crypto cache store");
    99→      }
   100→    } catch (error) {
   101→      console.warn("Failed to clear crypto store:", error);
   102→    }
   103→  }
   104→
   105→  /** Initialize client with error handling for RTC warnings */
   106→  public static async initialize(serverUrl: string) {
   107→    this.instance = await new ClientBuilder()
   108→      .serverNameOrHomeserverUrl(serverUrl)
   109→      .sessionPaths(dataPath, cachePath) // enables persistent stores (needed for E2EE)
   110→      .autoEnableBackups(false)
   111→      .build();
   112→  }
   113→
   114→  public static getServerName = () => {
   115→    if (!this.instance) return null;
   116→    return this.instance.server() || this.instance.homeserver();
   117→  };
   118→
   119→  // public static isLoggedIn = () => this.instance.isLoggedIn();
   120→
   121→  /** Check if there are stored credentials available for auto-login */
   122→  public static hasStoredCredentials = (): boolean => {
   123→    return MatrixStorage.hasStoredCredentials();
   124→  };
   125→
   126→  /** Attempt to restore session from stored credentials */
   127→  public static restoreSession = async (): Promise<boolean> => {
   128→    try {
   129→      const credentials = MatrixStorage.getLoginCredentials();
   130→
   131→      if (!credentials) return false;
   132→
   133→      await this.initialize(credentials.baseUrl);
   134→
   135→      if (!this.instance) throw new Error("Failed to initialize client");
   136→
   137→      // Create client with stored credentials
   138→      await this.instance.restoreSession({
   139→        accessToken: credentials.accessToken,
   140→        refreshToken: credentials.refreshToken,
   141→        userId: credentials.userId,
   142→        deviceId: credentials.deviceId,
   143→        homeserverUrl: credentials.baseUrl,
   144→        oidcData: undefined,
   145→        slidingSyncVersion: SlidingSyncVersion.Native,
   146→      });
   147→
   148→      // Verify the session is valid by making a server request
   149→      try {
   150→        this.profile = await this.instance.getProfile(credentials.userId);
   151→      } catch (error) {
   152→        console.warn("Session validation failed:", error);
   153→        throw new Error("Session is invalid or expired");
   154→      }
   155→
   156→      this.syncService = await this.instance.syncService().finish();
   157→
   158→      if (!this.syncService) {
   159→        throw new Error("Failed to initialize sync service");
   160→      }
   161→
   162→      await this.syncService.start();
   163→
   164→      // Update atoms so providers can react to the initialized service
   165→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   166→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   167→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   168→
   169→      return true;
   170→    } catch (error) {
   171→      console.warn("Failed to restore session:", error);
   172→
   173→      // Clear both credentials and crypto store to ensure clean state
   174→      MatrixStorage.clearLoginCredentials();
   175→      await this.clearCryptoStore();
   176→
   177→      // Reset the instance so it can be recreated fresh
   178→      this.instance = null;
   179→      this.syncService = null;
   180→
   181→      // Clear atoms
   182→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   183→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   184→
   185→      return false;
   186→    }
   187→  };
   188→
   189→  /** Call this after logging in to create a new client instance with the provided account.  */
   190→  public static setup = async (params: Session) => {
   191→    // Clear any existing crypto store to prevent device ID mismatches
   192→    await this.clearCryptoStore();
   193→
   194→    // Stop and clear existing instances
   195→    if (this.syncService) await this.syncService.stop();
   196→    this.instance = null;
   197→    this.syncService = null;
   198→
   199→    // Save credentials for future auto-login
   200→    MatrixStorage.saveLoginCredentials({
   201→      accessToken: params.accessToken,
   202→      refreshToken: params.refreshToken,
   203→      userId: params.userId,
   204→      deviceId: params.deviceId,
   205→      baseUrl: params.homeserverUrl,
   206→    });
   207→
   208→    // Create a fresh client instance and configure it with the session + sliding sync
   209→    await this.initialize(params.homeserverUrl);
   210→
   211→    if (!this.instance) throw new Error("Failed to initialize client");
   212→
   213→    // Use local variable to help TypeScript with type narrowing
   214→    const client: ClientInterface = this.instance;
   215→
   216→    await client.restoreSession({
   217→      accessToken: params.accessToken,
   218→      refreshToken: params.refreshToken,
   219→      userId: params.userId,
   220→      deviceId: params.deviceId,
   221→      homeserverUrl: params.homeserverUrl,
   222→      oidcData: undefined,
   223→      slidingSyncVersion: SlidingSyncVersion.Native,
   224→    });
   225→
   226→    // Verify the session is valid by making a server request
   227→    // Use the params.userId since client.userId() might not be populated yet
   228→    try {
   229→      this.profile = await client.getProfile(params.userId);
   230→    } catch (error) {
   231→      console.warn("Session validation failed:", error);
   232→      throw new Error("Session is invalid or expired");
   233→    }
   234→
   235→    this.syncService = await client.syncService().finish();
   236→
   237→    if (!this.syncService) throw new Error("Failed to initialize sync service");
   238→
   239→    await this.syncService.start();
   240→    await client.encryption().waitForE2eeInitializationTasks();
   241→
   242→    // Check if we need to bootstrap cross-signing or enable backups
   243→    try {
