   635→    if (!filteredUserIds.length) {
   636→      return [];
   637→    }
   638→
   639→    try {
   640→      const profilePromises = filteredUserIds.map((userId) =>
   641→        this.instance?.getProfile(userId),
   642→      );
   643→      const profiles = await Promise.allSettled(profilePromises);
   644→      return profiles
   645→        .filter((p) => p.status === "fulfilled")
   646→        .map((p) => p.value)
   647→        .filter((p) => p !== undefined);
   648→    } catch (error) {
   649→      console.error("Failed to get read receipt users:", error);
   650→      return [];
   651→    }
   652→  };
