    15→
    16→const playButtonTransition = animateParallel(
    17→  { opacity: [0, 1], width: [0, 48] },
    18→  { duration: 200, native: false },
    19→);
    20→
    21→interface Props {
    22→  roomId: string;
    23→  isRecording: boolean;
    24→  isRecorded: boolean;
