    30→const normalizePath = (path: string) => path.replace("file://", "");
    31→
    32→export const VoiceRecordButton: FC<Props> = ({
    33→  roomId,
    34→  isRecording,
    35→  isRecorded,
    36→  message,
    37→  setIsRecorded,
    38→  setIsRecording,
    39→}) => {
    40→  const durationMs = useRef(0);
    41→  const [duration, setDuration] = useState(0);
    42→  const recordingPath = useRef<string | null>(null);
    43→  const [isSending, setIsSending] = useState(false);
    44→
    45→  const startRecording = async () => {
    46→    try {
    47→      const hasMic = await checkPermission(PermissionType.MICROPHONE);
    48→      if (!hasMic) {
    49→        Alert.alert(
    50→          "Microphone permission required",
    51→          "Please grant microphone permission to record voice messages.",
    52→          [
    53→            {
    54→              text: "Cancel",
    55→              style: "cancel",
    56→            },
    57→            {
    58→              text: "Open settings",
    59→              onPress: () => Linking.openSettings(),
    60→            },
    61→          ],
    62→        );
    63→        return;
    64→      }
    65→
    66→      RecorderService.createListener((e) => {
    67→        setDuration(e.currentPosition);
    68→        durationMs.current = e.currentPosition;
    69→      });
    70→
    71→      await RecorderService.start();
    72→      setIsRecording(true);
    73→      setIsRecorded(true);
    74→    } catch (error) {
    75→      Toast.show({ type: "error", text1: "Failed to start recording" });
    76→      console.error(error);
    77→    }
    78→  };
    79→
    80→  const stopRecording = async () => {
    81→    try {
    82→      const path = await RecorderService.stop();
    83→      RecorderService.removeListener();
    84→      recordingPath.current = normalizePath(path);
    85→      setIsRecording(false);
    86→    } catch (error) {
    87→      Toast.show({
    88→        type: "error",
    89→        text1:
    90→          error instanceof Error ? error.message : "Failed to stop recording",
    91→      });
    92→      console.error(error);
    93→    }
    94→  };
    95→
    96→  const sendRecording = async () => {
    97→    try {
    98→      setIsSending(true);
    99→      setIsRecorded(false);
   100→
   101→      if (isRecording) await stopRecording();
   102→
   103→      if (!recordingPath.current) return;
   104→
   105→      const stats = await RNBlobUtil.fs.stat(recordingPath.current);
   106→
   107→      const room = MatrixService.instance?.getRoom(roomId);
   108→      if (!room) return Promise.reject(new Error("Room not found"));
   109→      const timeline = await room.timeline();
   110→
   111→      timeline.sendAudio(
   112→        {
   113→          source: new UploadSource.File({
   114→            filename: recordingPath.current.replace("file://", ""),
   115→          }),
   116→          caption: undefined,
   117→          formattedCaption: undefined,
   118→          mentions: undefined,
   119→          inReplyTo: undefined,
   120→        },
   121→        {
   122→          duration: durationMs.current,
   123→          size: BigInt(stats.size || 0),
   124→          mimetype: "audio/m4a",
   125→        },
   126→      );
   127→
   128→      // Don't immediately delete the recording - the SDK needs it for upload
   129→      // Clean up UI state but keep the file so it can be played while uploading
   130→      setDuration(0);
   131→      durationMs.current = 0;
   132→      recordingPath.current = null;
   133→    } catch (error) {
   134→      Toast.show({ type: "error", text1: "Failed to send voice message" });
   135→      console.error(error);
   136→    } finally {
   137→      setIsSending(false);
   138→    }
   139→  };
   140→
   141→  const removeRecording = async () => {
   142→    if (!recordingPath.current) return;
   143→    await removeFile(recordingPath.current);
   144→    setDuration(0);
   145→    durationMs.current = 0;
   146→    recordingPath.current = null;
   147→  };
   148→
   149→  const deleteRecording = async () => {
   150→    try {
   151→      if (isRecording) await stopRecording();
