   160→    /**Stop the recording when the app goes to background */
   161→    const listener = AppState.addEventListener("change", (nextAppState) => {
   162→      if (nextAppState.match(/inactive|background/) && isRecording) {
   163→        stopRecording();
   164→      }
   165→    });
   166→
   167→    return () => listener.remove();
   168→  }, [isRecording]);
   169→
   170→  useEffect(() => {
   171→    if (message || isRecording || isRecorded) playButtonTransition.reverse();
   172→    else playButtonTransition.start();
   173→  }, [message, isRecording, isRecorded]);
   174→
   175→  return (
   176→    <Block flexDirection="row" flex={isRecording || isRecorded ? 1 : 0} gap={8}>
   177→      <Block
   178→        height={48}
   179→        align="center"
   180→        justify="center"
   181→        animations={playButtonTransition.animations}
   182→      >
   183→        <Button.Outline
   184→          disabled={isSending}
   185→          style={styles.container}
   186→          onPress={startRecording}
   187→        >
   188→          <Image
   189→            source={require("assets/icons/microphone.png")}
   190→            style={styles.image}
   191→          />
   192→        </Button.Outline>
   193→      </Block>
   194→      {(isRecording || isRecorded) && (
   195→        <Block flexDirection="row" flex={1} gap={8}>
   196→          <Button.Wrapper
   197→            disabled={isSending}
   198→            style={styles.container}
   199→            onPress={deleteRecording}
   200→          >
   201→            <Image
   202→              source={require("assets/icons/trash.png")}
   203→              tintColor={Colors.error}
   204→              style={styles.image}
   205→            />
   206→          </Button.Wrapper>
   207→          <Block
   208→            flex={1}
   209→            align="center"
   210→            gap={12}
   211→            flexDirection="row"
   212→            height={44}
   213→            paddings={[10, 16]}
   214→            background={Colors.white20}
   215→            border={{ borderRadius: 40 }}
   216→          >
   217→            <AudioIndicator runAnimation={isRecording} />
   218→            <Text>{getTimeDuration(duration)}</Text>
   219→          </Block>
   220→          <Button.Wrapper
   221→            style={styles.container}
   222→            disabled={isSending}
   223→            onPress={isRecording ? stopRecording : sendRecording}
