   225→            <Block
   226→              height={48}
   227→              width={48}
   228→              align="center"
   229→              justify="center"
   230→              background={isRecording ? Colors.white20 : Colors.primary}
   231→              border={{
   232→                borderRadius: 24,
   233→              }}
   234→            >
   235→              <Image
   236→                source={
