    23→
    24→/** Maximum age for a verification request to be considered valid (5 minutes) */
    25→const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;
    26→
    27→/** Check if an event is a verification request */
    28→const isVerificationRequest = (event: EventTimelineItem): boolean => {
    29→  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
    30→  const kind = event.content.inner.content.kind;
    31→  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
    32→  const msgType = kind.inner.content.msgType;
    33→  return (
    34→    msgType?.tag === MessageType_Tags.Other &&
    35→    msgType.inner.msgtype === "m.key.verification.request"
    36→  );
    37→};
    38→
    39→/** Check if a verification request is recent enough to be handled */
    40→const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
    41→  const eventTimestamp = Number(event.timestamp);
    42→  const now = Date.now();
    43→  const age = now - eventTimestamp;
    44→  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
    45→};
    46→
    47→interface Props {
    48→  room: RoomInterface | undefined;
    49→  roomId: string;
    50→}
    51→
    52→export const useRoomTimeline = ({ room, roomId }: Props) => {
    53→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    54→  const [loadingMessage, setLoadingMessage] = useState(true);
    55→  /** Track processed verification request IDs to avoid duplicates */
    56→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
    57→  const [refreshing, setRefreshing] = useState(false);
    58→  const [updateTrigger, setUpdateTrigger] = useState(0);
    59→  const eventIdsRef = useRef<Set<string>>(new Set());
    60→  const timelineRef = useRef<TimelineInterface | null>(null);
    61→  const isPaginatingRef = useRef(false);
    62→  const timelinePaginateNumber = useRef<number>(20);
    63→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    64→
    65→  const upsertEvents = (incoming: EventTimelineItem[]) => {
    66→    setEvents((prev) => {
    67→      const next = [...prev];
    68→      for (const e of incoming) {
    69→        const id = getEventId(e);
    70→        if (!id) continue;
    71→        if (!eventIdsRef.current.has(id)) {
    72→          eventIdsRef.current.add(id);
    73→          next.push(e);
    74→        }
    75→      }
    76→      return next;
    77→    });
    78→  };
    79→
    80→  const handleVerificationRequest = (info: {
    81→    senderId: string;
    82→    flowId: string;
    83→  }) => {
    84→    setVerificationStatus("incomingRequest");
    85→    NavigationContainerRef.navigate("verifyUser", {
    86→      userId: info.senderId,
    87→      flowId: info.flowId,
    88→    });
    89→  };
    90→
    91→  const checkForVerificationRequests = useCallback(
    92→    (incoming: EventTimelineItem[]) => {
    93→      for (const event of incoming) {
    94→        if (event.isOwn) continue;
    95→
    96→        if (
    97→          !isVerificationRequest(event) ||
    98→          !isRecentVerificationRequest(event)
    99→        ) {
   100→          continue;
   101→        }
   102→
   103→        const flowId = getEventId(event);
   104→        if (!flowId) continue;
   105→
   106→        if (processedVerificationRequestsRef.current.has(flowId)) continue;
   107→
   108→        processedVerificationRequestsRef.current.add(flowId);
   109→
   110→        handleVerificationRequest({
   111→          senderId: event.sender,
   112→          flowId,
   113→        });
   114→
   115→        // Only handle one at a time
   116→        break;
   117→      }
   118→    },
   119→    [],
   120→  );
   121→
   122→  const markAsRead = async () => {
   123→    if (!room) return;
