   183→            setUpdateTrigger((prev) => prev + 1);
   184→            diffs.forEach((diff) => {
   185→              const change = diff.tag;
   186→              switch (change) {
   187→                case TimelineDiff_Tags.Append: {
   188→                  const newItems = diff.inner.values;
   189→                  if (newItems.length) {
   190→                    const eventItems = newItems
   191→                      .map((i) => i.asEvent())
   192→                      .filter((i): i is EventTimelineItem => !!i);
