   212→                  const ev = value.asEvent();
   213→                  if (ev) {
   214→                    const id = getEventId(ev);
   215→                    if (!id) break;
   216→
   217→                    setEvents((prev) => {
   218→                      const next = [...prev];
   219→                      // Guard against out-of-range (indexes may include non-event items upstream)
   220→                      if (index >= 0 && index < next.length) {
   221→                        // Check if we're updating the same event or creating a duplicate
   222→                        const existingId = getEventId(next[index]);
   223→                        if (existingId === id || !eventIdsRef.current.has(id)) {
   224→                          next[index] = ev;
   225→                        }
   226→                      } else {
   227→                        // If index doesn't line up, check for duplicates before adding
   228→                        if (!eventIdsRef.current.has(id)) {
   229→                          next.push(ev);
   230→                        }
   231→                      }
