   233→                      eventIdsRef.current = new Set(
   234→                        next.map(getEventId).filter(Boolean) as string[],
   235→                      );
   236→                      return next;
   237→                    });
   238→                  }
   239→                  break;
   240→                }
   241→                case TimelineDiff_Tags.Remove: {
   242→                  const { index: removeIndex } = diff.inner;
   243→                  setEvents((prev) => {
   244→                    const next = prev.filter((_, idx) => idx !== removeIndex);
   245→                    eventIdsRef.current = new Set(
   246→                      next.map(getEventId).filter(Boolean) as string[],
   247→                    );
   248→                    return next;
   249→                  });
   250→                  break;
   251→                }
   252→                case TimelineDiff_Tags.PushFront: {
   253→                  const { value } = diff.inner;
   254→                  const ev = value.asEvent();
   255→                  if (ev) {
   256→                    const id = getEventId(ev);
   257→                    if (!id) break;
   258→
   259→                    setEvents((prev) => {
   260→                      // Check for duplicate inside setState to prevent race conditions
   261→                      if (eventIdsRef.current.has(id)) return prev;
   262→                      eventIdsRef.current.add(id);
   263→                      return [ev, ...prev];
   264→                    });
   265→                    checkForVerificationRequests([ev]);
   266→                  }
   267→                  break;
   268→                }
   269→                case TimelineDiff_Tags.PushBack: {
   270→                  const { value } = diff.inner;
   271→                  const ev = value.asEvent();
   272→                  if (ev) {
   273→                    const id = getEventId(ev);
   274→                    if (!id) break;
   275→
   276→                    setEvents((prev) => {
   277→                      // Check for duplicate inside setState to prevent race conditions
   278→                      if (eventIdsRef.current.has(id)) return prev;
   279→                      eventIdsRef.current.add(id);
   280→                      return [...prev, ev];
   281→                    });
   282→                    checkForVerificationRequests([ev]);
   283→                  }
   284→                  break;
   285→                }
   286→                case TimelineDiff_Tags.Reset: {
   287→                  const resetItems = diff.inner.values;
   288→                  if (resetItems.length) {
   289→                    const eventItems = resetItems
   290→                      .map((i) => i.asEvent())
   291→                      .filter((i): i is EventTimelineItem => !!i);
   292→
   293→                    // Deduplicate events in case Reset contains duplicates
   294→                    const seenIds = new Set<string>();
   295→                    const uniqueEvents: EventTimelineItem[] = [];
   296→
   297→                    for (const event of eventItems) {
   298→                      const id = getEventId(event);
   299→                      if (id && !seenIds.has(id)) {
   300→                        seenIds.add(id);
   301→                        uniqueEvents.push(event);
   302→                      }
   303→                    }
   304→
   305→                    eventIdsRef.current = seenIds;
   306→                    setEvents(uniqueEvents);
   307→                  }
   308→                  break;
   309→                }
   310→                case TimelineDiff_Tags.Truncate: {
   311→                  const { length: cut } = diff.inner;
   312→                  setEvents((prev) => {
   313→                    const next = prev.slice(0, cut);
   314→                    eventIdsRef.current = new Set(
   315→                      next.map(getEventId).filter(Boolean) as string[],
   316→                    );
   317→                    return next;
   318→                  });
   319→                  break;
   320→                }
   321→                default:
   322→                  console.log("Unknown timeline change type:", change);
   323→              }
   324→            });
   325→          },
   326→        });
   327→      } catch (error) {
